#pragma once
// Thin layer over the per-platform differences in the DeckLink SDK:
// COM vs. dispatch functions, and BSTR / CFStringRef / const char* strings.

#ifdef _WIN32
  #ifndef NOMINMAX
  #define NOMINMAX
  #endif
  #include <windows.h>
  #include "DeckLinkAPI_h.h"   // generated by MIDL from the SDK's DeckLinkAPI.idl
  using dl_string = BSTR;
  using dl_bool = BOOL;
#elif defined(__APPLE__)
  #include "DeckLinkAPI.h"
  using dl_string = CFStringRef;
  using dl_bool = bool;
#else
  #include "DeckLinkAPI.h"
  using dl_string = const char*;
  using dl_bool = bool;
#endif

#include <string>

namespace dlp {
bool initialise();   // CoInitialize on Windows, no-op elsewhere
void shutdown();
std::string toStd(dl_string s);  // converts and frees the SDK string
IDeckLinkIterator* createIterator();
IDeckLinkVideoConversion* createVideoConversion();
bool iidEquals(REFIID a, REFIID b);
}  // namespace dlp
